public static int calculateTimeNeeded(int N) {
    if (N <= 2)
        return 0;

    int time = 0;
    int n = N >> 1; // Equivalent to (N - 1) / 2 + 1 for odd numbers
    time += 2 * (n - 1); // Adding the time taken to move people to the opposite sides for each half
    time += 2 * (n - 2); // Adding the time taken to move people to the opposite sides for each half in the second half

    if (N % 2 != 0) { // If N is odd, add an additional minute for the last person
        time++;
    }

    return time;
}
