        for (int i = 0; i < len; i++) {
            for (int j = len; j > i && j - i > maxLength; j--) {
                if (str.contains(str.substring(i, j)) || str.contains(str.substring(j - i))) {
                    maxLength = Math.max(maxLength, j - i);
