import java.util.List;

public class AppleCollection {

    /**
     * Given a tree with n nodes and edges, and a boolean array hasApple indicating if each node has an apple.
     * Starting from node 0, return the minimum time required to collect all the apples and return to node 0.
     *
     * @param n        the number of nodes in the tree
     * @param edges    the edges of the tree (list of integer arrays where each array contains two integers: the parent and child)
     * @param hasApple an array indicating if each node has an apple
     * @return the minimum time required to collect all the apples and return to node 0
     */
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> tree = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tree.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }

        int time = dfs(tree, hasApple, 0, -1);
        return time == 0 ? 0 : time - 2; // Subtract 2 to exclude the edge back to the root
    }

    /**
     * Helper method to perform depth-first search on the tree.
     *
     * @param tree    the tree represented as a list of lists of integers
     * @param hasApple an array indicating if each node has an apple
     * @param node    the current node being visited
     * @param parent the parent node of the current node
     * @return the minimum time required to visit the current node, including the time to collect apples
     */
    private int dfs(List<List<Integer>> tree, boolean[] hasApple, int node, int parent) {
        int time = 0;
        for (int child : tree.get(node)) {
            if (child != parent) {
                int subTreeTime = dfs(tree, hasApple, child, node);
                if (subTreeTime > 0 || hasApple[child]) {
                    time += subTreeTime + (parent != -1);
                }
            }
        }
        return time;
    }

