public class MinimumTimeCollectApples {

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Set<Integer> visited = new HashSet<>();
        Set<Integer> seen = new HashSet<>();
        // Build the adjacency list from the edges
        List<List<Integer>> adjacencyList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjacencyList.get(edge[0]).add(edge[1]);
            adjacencyList.get(edge[1]).add(edge[0]);
        }

        return dfsN(0, adjacencyList, hasApple, visited, seen);
    }

    private int dfsN(int node, List<List<Integer>> adjList, boolean[] hasApple, Set<Integer> visited, Set<Integer> seen) {
        if (visited.contains(node)) {
            return 0;
        }
        visited.add(node);
        seen.add(node);
        int time = 0;
        for (int neighbor : adjList.get(node)) {
            time += dfsN(neighbor, adjList, hasApple, visited, seen);
            if (hasApple[neighbor] || seen.contains(neighbor)) {
                time += 2;
            }
        }
        return time;
    }

