    final int[] ALPHABET = new int[] { 'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z' };
    return getSmallestString(n, k, ALPHABET);
}

private String getSmallestString(int n, int k, int[] alphabet) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n - 1; i++) {
        sb.append(alphabet[i]);
        k -= i + 1;
    }
    sb.append(alphabet[n - 1]);
    k -= alphabet.length - 1;
    if (k > 0) {
        sb.append(alphabet[n - 1] - k);
        k = 0;
    } else {
        String res = sb.toString();
        sb.reverse();
        return res;
    }
    return sb.toString().concat(new StringBuilder().reverse().toString());
}

