public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n % 2 != 0) {
        return 0;
    }
    int[] counter = new int[n];
    int[] sum = new int[n];
    int[] prevprev = new int[n];
    int[] prev = new int[n];
    for (int i = 0; i < sqrt(n); i++) {
        prevprev[i] = i;
    }
    for (int i = sqrt(n); i < n; i++) {
        prev[i] = i - sqrt(n);
    }
    // Find the first perfect square pair
    for (int i = 0; i < sqrt(n); i++) {
        for (int j = i + 1; j < sqrt(n); j++) {
            int s = A[i] + A[j];
            int p = (int) Math.sqrt(s);
            while (p * p != s) {
                p++;
            }
            if (p * p == s) {
                counter[i] = counter[j] = 1;
                sum[i] = sum[j] = p;
                break;
            }
        }
    }
    // Enable item replacement
    for (int i = sqrt(n); i < n; i++) {
        counter[i] = 0;
        if (sum[i] == 1) {
            counter[i] = 1;
            continue;
        }
        for (int j = i - sqrt(n); j < i; j++) {
            if (sum[i] == j + prev[j]) {
                int c = counter[i] + counter[j];
                counter[i] += c;
            }
        }
    }
    return counter[sqrt(n) - 1];
}
