        if (square * square == A[i]) {
            squareArray[i] = square;
        } else {
            return 0; // A[i] is not a perfect square
        }
    }

    return helper(squareArray, new boolean[length], new Map<Integer, Integer>());
}

private static int helper(int[] array, boolean[] used, Map<Integer, Integer> map) {
    if (used.length == 0) {
        return 1;
    }

    int result = 0;
    for (int i = 0; i < used.length; i++) {
        if (used[i]) {
            continue;
        }

        if (i > 0 && array[i - 1] == array[i] && !used[i - 1]) {
            continue;
        }

        used[i] = true;
        map.put(array[i], i);
        result += helper(array, used, map);
        map.remove(array[i]);
        used[i] = false;
    }

    return result;
}
